/** The metal each glyph wears, keyed by app skin. `brand` is the original artwork. */
export const CAR_ICON_BY_SKIN = {
  crew:    { brand: CAR_ICON_CREW,    premium: CAR_ICON_CREW_PREMIUM,    ultra: CAR_ICON_CREW_ULTRA,    diamond: CAR_ICON_CREW_DIAMOND },
  compass: { brand: CAR_ICON_COMPASS, premium: CAR_ICON_COMPASS_PREMIUM, ultra: CAR_ICON_COMPASS_ULTRA, diamond: CAR_ICON_COMPASS_DIAMOND },
  view3d:  { brand: CAR_ICON_VIEW_3D, premium: CAR_ICON_VIEW_3D_PREMIUM,  ultra: CAR_ICON_VIEW_3D_ULTRA,  diamond: CAR_ICON_VIEW_3D_DIAMOND },
  view2d:  { brand: CAR_ICON_VIEW_2D, premium: CAR_ICON_VIEW_2D_PREMIUM,  ultra: CAR_ICON_VIEW_2D_ULTRA,  diamond: CAR_ICON_VIEW_2D_DIAMOND },
  hz_police: { brand: CAR_ICON_HZ_POLICE_BRAND, premium: CAR_ICON_HZ_POLICE_PREMIUM, ultra: CAR_ICON_HZ_POLICE_ULTRA, diamond: CAR_ICON_HZ_POLICE_DIAMOND },
  hz_crash: { brand: CAR_ICON_HZ_CRASH_BRAND, premium: CAR_ICON_HZ_CRASH_PREMIUM, ultra: CAR_ICON_HZ_CRASH_ULTRA, diamond: CAR_ICON_HZ_CRASH_DIAMOND },
  hz_hazard: { brand: CAR_ICON_HZ_HAZARD_BRAND, premium: CAR_ICON_HZ_HAZARD_PREMIUM, ultra: CAR_ICON_HZ_HAZARD_ULTRA, diamond: CAR_ICON_HZ_HAZARD_DIAMOND },
  hz_traffic: { brand: CAR_ICON_HZ_TRAFFIC_BRAND, premium: CAR_ICON_HZ_TRAFFIC_PREMIUM, ultra: CAR_ICON_HZ_TRAFFIC_ULTRA, diamond: CAR_ICON_HZ_TRAFFIC_DIAMOND },
  hz_camera: { brand: CAR_ICON_HZ_CAMERA_BRAND, premium: CAR_ICON_HZ_CAMERA_PREMIUM, ultra: CAR_ICON_HZ_CAMERA_ULTRA, diamond: CAR_ICON_HZ_CAMERA_DIAMOND },
  hz_compass: { brand: CAR_ICON_HZ_COMPASS_BRAND, premium: CAR_ICON_HZ_COMPASS_PREMIUM, ultra: CAR_ICON_HZ_COMPASS_ULTRA, diamond: CAR_ICON_HZ_COMPASS_DIAMOND },
} as const;

export type CarGlyph = keyof typeof CAR_ICON_BY_SKIN;

/** Resolve a glyph for the active skin. Unknown skins fall back to the brand art. */
export function carIcon(glyph: CarGlyph, skin: VisualTier): CarIcon {
  const set = CAR_ICON_BY_SKIN[glyph];
  return (set && (set as any)[skin]) || set.brand;
}
